    const std::string& GetGameDirectory()
    {
        static const std::string gameDirectory = []() -> std::string
        {
            char exePath[MAX_PATH]{};
            const DWORD length = GetModuleFileNameA(nullptr, exePath, MAX_PATH);
            if (length == 0 || length >= MAX_PATH)
                return std::string(".");

            char* slash = strrchr(exePath, '\\');
            if (slash != nullptr)
                *slash = '\0';

            return std::string(exePath);
        }();

        return gameDirectory;
    }

    bool DirectoryExists(const std::string& path)
    {
        const DWORD attributes = GetFileAttributesA(path.c_str());
        return attributes != INVALID_FILE_ATTRIBUTES &&
            (attributes & FILE_ATTRIBUTE_DIRECTORY) != 0;
    }

    bool FileExists(const std::string& path)
    {
        const DWORD attributes = GetFileAttributesA(path.c_str());
        return attributes != INVALID_FILE_ATTRIBUTES &&
            (attributes & FILE_ATTRIBUTE_DIRECTORY) == 0;
    }

    bool EnsureDirectoryExists(const std::string& path)
    {
        if (DirectoryExists(path))
            return true;

        if (CreateDirectoryA(path.c_str(), nullptr) != FALSE)
            return true;

        return GetLastError() == ERROR_ALREADY_EXISTS && DirectoryExists(path);
    }

    bool StartsWithInsensitive(const std::string& value, const std::string& prefix)
    {
        if (prefix.empty() || value.size() < prefix.size())
            return false;

        return _strnicmp(value.c_str(), prefix.c_str(), prefix.size()) == 0;
    }

    std::string GetEnvironmentPath(const char* variable)
    {
        char buffer[MAX_PATH]{};
        const DWORD length = GetEnvironmentVariableA(variable, buffer, MAX_PATH);
        if (length == 0 || length >= MAX_PATH)
            return std::string();
        return std::string(buffer);
    }

    bool IsProtectedProgramFilesPath(const std::string& path)
    {
        const std::string programFilesX86 = GetEnvironmentPath("ProgramFiles(x86)");
        const std::string programFiles = GetEnvironmentPath("ProgramFiles");

        return (!programFilesX86.empty() && StartsWithInsensitive(path, programFilesX86)) ||
            (!programFiles.empty() && StartsWithInsensitive(path, programFiles));
    }

    bool CanWriteDirectoryDirectly(const std::string& directory)
    {
        std::string probe = directory;
        if (!probe.empty() && probe.back() != '\\')
            probe += '\\';
        probe += "RaimiHook_write_test.tmp";

        HANDLE file = CreateFileA(
            probe.c_str(),
            GENERIC_WRITE,
            FILE_SHARE_READ | FILE_SHARE_WRITE,
            nullptr,
            CREATE_ALWAYS,
            FILE_ATTRIBUTE_TEMPORARY,
            nullptr);

        if (file == INVALID_HANDLE_VALUE)
            return false;

        CloseHandle(file);
        DeleteFileA(probe.c_str());
        return true;
    }

    void ResolveResourceStorage()
    {
        if (s_ResourceStorageResolved)
            return;

        // XESM3 public layout is always beside the Spider-Man 3 executable.
        // Mods live at <game>\Mods exactly like an exWoS-style drop-in loader.
        s_ResourceStorageRoot = GetGameDirectory();
        s_ResourceStorageFallback = false;
        s_ResourceStorageResolved = true;
    }

    std::string GetResourcePath(const char* fileName)
    {
        ResolveResourceStorage();
        std::string path = s_ResourceStorageRoot;
        if (!path.empty() && path.back() != '\\')
            path += '\\';
        path += fileName;
        return path;
    }

    const char* ResourceTypeName(uint32_t type)
    {
        switch (type)
        {
        case 0x00584554: return "TEX";
        case 0x00005846: return "FX";
        case 0x0054414D: return "MAT";
        case 0x4853454D: return "MESH";
        case 0x48524F4D: return "MORH";
        case 0x4D494E41: return "ANIM";
        case 0x4D4E4153: return "SANM";
        case 0x4C4B5341: return "ASKL";
        case 0x4C454B53: return "SKEL";
        case 0x544E4F46: return "FONT";
        default: return "????";
        }
    }

    uint32_t ResourceTypeFromExtension(const std::string& extension)
    {
        if (_stricmp(extension.c_str(), ".tex") == 0) return 0x00584554;
        if (_stricmp(extension.c_str(), ".fx") == 0) return 0x00005846;
        if (_stricmp(extension.c_str(), ".mat") == 0) return 0x0054414D;
        if (_stricmp(extension.c_str(), ".mesh") == 0) return 0x4853454D;
        if (_stricmp(extension.c_str(), ".morh") == 0) return 0x48524F4D;
        if (_stricmp(extension.c_str(), ".anim") == 0) return 0x4D494E41;
        if (_stricmp(extension.c_str(), ".sanm") == 0) return 0x4D4E4153;
        if (_stricmp(extension.c_str(), ".askl") == 0) return 0x4C4B5341;
        if (_stricmp(extension.c_str(), ".skel") == 0) return 0x4C454B53;
        if (_stricmp(extension.c_str(), ".font") == 0) return 0x544E4F46;
        return 0; // unknown future classes
    }

    uint64_t MakeLooseResourceKey(uint32_t type, uint32_t hash)
    {
        return (static_cast<uint64_t>(type) << 32) | hash;
    }

    uint32_t HashResourceName(const char* name)
    {
        uint32_t hash = 0;
        if (name == nullptr)
            return hash;

        while (*name != '\0')
        {
            unsigned char c = static_cast<unsigned char>(*name++);
            if (c >= 'A' && c <= 'Z')
                c = static_cast<unsigned char>(c + ('a' - 'A'));
            hash = hash * 33u + c;
        }
        return hash;
    }

