    struct SM3NativeTexHeader
    {
        uint32_t runtimeContext;      // +00 - runtime-owned after APKF fixup/load
        uint32_t runtimeIndex;        // +04 - runtime-owned
        uint32_t namePointerOrReloc;  // +08 - raw relocation token on disk / pointer at runtime
        uint32_t nameHash;            // +0C
        uint32_t flags;               // +10
        uint32_t runtimeTextureNode;  // +14 - runtime-owned D3D tracking node
        uint32_t width;               // +18
        uint32_t height;              // +1C
        uint32_t depth;               // +20
        uint32_t mipCount;            // +24
        uint32_t format;              // +28 (D3DFORMAT/FourCC)
        uint32_t usage;               // +2C - runtime load path normally sets 0
        uint32_t textureKind;         // +30 - runtime: 3=2D, 4=volume, 5=cube
        uint32_t unknown34;           // +34
        uint32_t linkedImage;         // +38
        uint32_t unknown3C;           // +3C
        uint32_t auxAllocation;       // +40
    };

    static_assert(sizeof(SM3NativeTexHeader) == SM3_NATIVE_TEX_HEADER_SIZE, "SM3 native TEX header must be 0x44 bytes");

    struct RuntimeTexPatchState
    {
        void* originalPhys = nullptr;
        uint32_t width = 0;
        uint32_t height = 0;
        uint32_t depth = 0;
        uint32_t mipCount = 0;
        uint32_t format = 0;
    };


    constexpr uint32_t SM3_MAT_IMPL_SM_PREFAB = 0x8A54C3CF;
    constexpr uint32_t SM3_MAT_IMPL_SM_PHAT = 0x99A1E0EC;
    constexpr size_t SM3_MAT_COMMON_SIZE = 0x20;
    constexpr size_t SM3_MAT_SM_PHAT_SIZE = 0xA0;

    struct NativeMatDwordChange
    {
        size_t offset = 0;
        uint32_t oldValue = 0;
        uint32_t newValue = 0;
    };

    struct NativeMatReferenceRequest
    {
        size_t offset = 0;
        uint32_t resourceType = 0;
        uint32_t resourceHash = 0;
        std::string resourceName;
    };

    bool IsSmPhatStage2TexReferenceOffset(size_t offset)
    {
        // Raw H07 APKF resource-reference records confirmed these as TEX slots
        // for sm_phat. Stage 2 deliberately excludes +14 (COWB) for now.
        switch (offset)
        {
        case 0x28:
        case 0x2C:
        case 0x30:
        case 0x34:
        case 0x38:
        case 0x3C:
        case 0x78:
        case 0x7C:
            return true;
        default:
            return false;
        }
    }

    // Stage 1 intentionally preserves all fields known to be APKF-fixed
    // pointers/resource references.  Only proven scalar/parameter ranges are
    // copied from the loose sm_phat MAT into the already-fixed runtime MAT.
    bool IsSmPhatStage1EditableOffset(size_t offset)
    {
        // Common scalar fields.
        if (offset == 0x0C || offset == 0x10 ||
            offset == 0x18 || offset == 0x1C ||
            offset == 0x20 || offset == 0x24)
            return true;

        // Renderer-consumed scalar/material parameter block.
        if (offset >= 0x40 && offset <= 0x74 && (offset & 3) == 0)
            return true;

        // UV/animation scalar block.
        if (offset >= 0x80 && offset <= 0x9C && (offset & 3) == 0)
            return true;

        return false;
    }

    int HexNibble(char c)
    {
        if (c >= '0' && c <= '9') return c - '0';
        if (c >= 'a' && c <= 'f') return c - 'a' + 10;
        if (c >= 'A' && c <= 'F') return c - 'A' + 10;
        return -1;
    }

    bool TryFindExplicitHashInText(const std::string& text, uint32_t& hash, size_t* tokenOffset = nullptr)
    {
        if (text.size() < 10)
            return false;

        for (size_t start = 0; start + 10 <= text.size(); ++start)
        {
            if (text[start] != '0' || (text[start + 1] != 'x' && text[start + 1] != 'X'))
                continue;

            uint32_t value = 0;
            bool valid = true;
            for (size_t i = 0; i < 8; ++i)
            {
                const int nibble = HexNibble(text[start + 2 + i]);
                if (nibble < 0)
                {
                    valid = false;
                    break;
                }
                value = (value << 4) | static_cast<uint32_t>(nibble);
            }

            if (!valid)
                continue;

            hash = value;
            if (tokenOffset != nullptr)
                *tokenOffset = start;
            return true;
        }

        return false;
    }

    std::string TrimAscii(const std::string& value)
    {
        const char* whitespace = " \t\r\n";
        const size_t first = value.find_first_not_of(whitespace);
        if (first == std::string::npos)
            return std::string();
        const size_t last = value.find_last_not_of(whitespace);
        return value.substr(first, last - first + 1);
    }

    std::string StripIniComment(const std::string& value)
    {
        size_t cut = std::string::npos;
        const size_t hashComment = value.find('#');
        const size_t semicolonComment = value.find(';');
        if (hashComment != std::string::npos)
            cut = hashComment;
        if (semicolonComment != std::string::npos && (cut == std::string::npos || semicolonComment < cut))
            cut = semicolonComment;
        return TrimAscii(cut == std::string::npos ? value : value.substr(0, cut));
    }

    void DeriveLooseResourceIdentity(const char* fileName, uint32_t& hash, std::string& logicalName, std::string& extension)
    {
        hash = 0;
        logicalName.clear();
        extension.clear();

        if (fileName == nullptr || *fileName == '\0')
            return;

        std::string stem(fileName);
        const size_t dot = stem.find_last_of('.');
        if (dot != std::string::npos)
        {
            extension = stem.substr(dot);
            stem.resize(dot);
        }

        if (stem.empty())
            return;

        size_t hashOffset = 0;
        if (TryFindExplicitHashInText(stem, hash, &hashOffset))
        {
            const size_t afterHash = hashOffset + 10;
            if (afterHash < stem.size() && stem[afterHash] == '.')
                logicalName = stem.substr(afterHash + 1);
            else
                logicalName = stem;

            // SM3 uses native .tex rather than WoS .wrap.tex. If a convenience
            // filename includes a trailing .wrap marker, do not make it part of
            // the logical resource name.
            if (logicalName.size() > 5 && _stricmp(logicalName.c_str() + logicalName.size() - 5, ".wrap") == 0)
                logicalName.resize(logicalName.size() - 5);
        }
        else
        {
            logicalName = stem;
            hash = HashResourceName(stem.c_str());
        }
    }

    bool EndsWithInsensitive(const std::string& value, const char* suffix)
    {
        if (suffix == nullptr)
            return false;

        const size_t suffixLength = strlen(suffix);
        if (suffixLength == 0 || value.size() < suffixLength)
            return false;

        return _stricmp(value.c_str() + value.size() - suffixLength, suffix) == 0;
    }

    bool IsStage2CMetadataFile(const char* fileName)
    {
        if (fileName == nullptr)
            return true;

        return _stricmp(fileName, "mod.ini") == 0 ||
            _stricmp(fileName, "mods.config.ini") == 0 ||
            _stricmp(fileName, "disabled.txt") == 0 ||
            _stricmp(fileName, "_stage2c_readme.txt") == 0 ||
            _stricmp(fileName, "_stage2c_exwos_style_readme.txt") == 0 ||
            _stricmp(fileName, "_stage2c_v3_sm3_archive_readme.txt") == 0 ||
            _stricmp(fileName, "_stage2c_v4_modroot_sm3_archive_readme.txt") == 0 ||
            _stricmp(fileName, "_stage2c_v5_mods_config_readme.txt") == 0 ||
            _stricmp(fileName, "_stage2c_v6_master_catalog_readme.txt") == 0 ||
            _stricmp(fileName, "filelist.txt") == 0 ||
            _stricmp(fileName, "filelist.apkf.txt") == 0 ||
            _stricmp(fileName, "ownership_manifest.json") == 0 ||
            _stricmp(fileName, "README_MOD_LOADER_READY.txt") == 0 ||
            _stricmp(fileName, "desktop.ini") == 0 ||
            _stricmp(fileName, "thumbs.db") == 0;
    }

    bool IsSupportedLooseResourceExtension(const std::string& extension)
    {
        return _stricmp(extension.c_str(), ".tex") == 0 ||
            _stricmp(extension.c_str(), ".fx") == 0 ||
            _stricmp(extension.c_str(), ".mesh") == 0 ||
            _stricmp(extension.c_str(), ".morh") == 0 ||
            _stricmp(extension.c_str(), ".anim") == 0 ||
            _stricmp(extension.c_str(), ".sanm") == 0 ||
            _stricmp(extension.c_str(), ".askl") == 0 ||
            _stricmp(extension.c_str(), ".skel") == 0 ||
            _stricmp(extension.c_str(), ".font") == 0 ||
            _stricmp(extension.c_str(), ".mat") == 0;
    }

    bool ParseExWosToggleValue(const char* value, int& outValue)
    {
        outValue = 0;
        if (value == nullptr || *value == '\0')
            return false;

        char* end = nullptr;
        const long parsed = strtol(value, &end, 10);
        if (end == value)
            return false;

        while (end != nullptr && (*end == ' ' || *end == '\t' || *end == '\r' || *end == '\n'))
            ++end;
        if (end != nullptr && *end != '\0')
            return false;

        // XESM3 public contract: keep configuration binary and simple.
        // 0 = disabled, 100 = enabled. No other numeric values are accepted.
        if (parsed != 0 && parsed != 100)
            return false;

        outValue = static_cast<int>(parsed);
        return true;
    }

    std::string GetModsConfigPath(const std::string& modsDirectory)
    {
        std::string path = modsDirectory;
        if (!path.empty() && path.back() != '\\')
            path += "\\";
        path += "mods.config.ini";
        return path;
    }

    void EnsureExWosStyleModsConfig(const std::string& modsDirectory)
    {
        const std::string configPath = GetModsConfigPath(modsDirectory);
        if (FileExists(configPath))
            return;

        // v0.1.0 INI HOTFIX:
        // ONLY <Game.exe>\Mods\mods.config.ini is authoritative.
        // Never migrate/copy a legacy root-level mods.config.ini here.
        // This prevents stale test/example settings from being resurrected.

        FILE* file = nullptr;
        if (fopen_s(&file, configPath.c_str(), "w") != 0 || file == nullptr)
            return;

        fputs(
            "; ============================================================\n"
            "; xeSM3 v0.1.0 - INI HOTFIX\n"
            "; Created by TSGAMING264\n"
            "; ============================================================\n"
            ";\n"
            "; ONLY this file is read:\n"
            ";   <Game.exe>\\Mods\\mods.config.ini\n"
            ";\n"
            "; 0   = Disabled\n"
            "; 100 = Enabled\n"
            ";\n"
            "; LAST assignment wins if a mod name appears more than once.\n"
            ";\n"
            "; Example:\n"
            ";   My Mod=100\n"
            ";\n"
            "; No example/test mod is enabled by default.\n"
            "; ============================================================\n"
            "\n"
            "[Info]\n"
            "SchemaVersion=1\n"
            "LoaderName=xeSM3\n"
            "PublicVersion=0.1.0\n"
            "\n"
            "[EnabledMods]\n"
            "\n"
            "; Add installed mod folders below.\n"
            "; My Mod=100\n",
            file);
        fclose(file);
    }

    bool LoadConfiguredModPackages(const std::string& modsDirectory, std::vector<ModPackageInfo>& packages)
    {
        packages.clear();

        // v0.1.0 INI HOTFIX:
        // Authoritative config is ONLY <Game.exe>\Mods\mods.config.ini.
        // No example/test configuration is embedded or auto-enabled.
        EnsureExWosStyleModsConfig(modsDirectory);

        const std::string configPath = GetModsConfigPath(modsDirectory);
        FILE* file = nullptr;
        if (fopen_s(&file, configPath.c_str(), "r") != 0 || file == nullptr)
            return false;

        bool inEnabledMods = false;
        bool firstLine = true;
        char buffer[2048]{};
        size_t order = 0;

        while (fgets(buffer, static_cast<int>(sizeof(buffer)), file) != nullptr)
        {
            std::string line = TrimAscii(buffer);

            // v0.1.0 INI HOTFIX: tolerate a UTF-8 BOM at the start of the file.
            // Without this, some Windows editors can make [EnabledMods] invisible
            // to the parser even though the INI looks correct in Notepad.
            if (firstLine)
            {
                firstLine = false;
                if (line.size() >= 3 &&
                    static_cast<unsigned char>(line[0]) == 0xEF &&
                    static_cast<unsigned char>(line[1]) == 0xBB &&
                    static_cast<unsigned char>(line[2]) == 0xBF)
                {
                    line.erase(0, 3);
                    line = TrimAscii(line);
                }
            }

            if (line.empty() || line[0] == '#' || line[0] == ';')
                continue;

            if (line.front() == '[' && line.back() == ']')
            {
                const std::string section = TrimAscii(line.substr(1, line.size() - 2));
                inEnabledMods = _stricmp(section.c_str(), "EnabledMods") == 0;
                continue;
            }

            if (!inEnabledMods)
                continue;

            const size_t equals = line.find('=');
            if (equals == std::string::npos)
                continue;

            const std::string name = TrimAscii(line.substr(0, equals));
            const std::string toggleText = StripIniComment(line.substr(equals + 1));
            if (name.empty() || toggleText.empty())
                continue;

            ModPackageInfo info{};
            info.name = name;
            info.root = modsDirectory + "\\" + name;
            info.validToggleValue = ParseExWosToggleValue(toggleText.c_str(), info.toggleValue);
            info.enabled = info.validToggleValue && info.toggleValue == 100;
            info.rootLoose = false;
            info.configOrder = order++;

            // v0.1.0 INI HOTFIX: normal INI behavior is LAST assignment wins.
            auto existing = std::find_if(
                packages.begin(),
                packages.end(),
                [&](const ModPackageInfo& candidate)
                {
                    return _stricmp(candidate.name.c_str(), name.c_str()) == 0;
                });

            if (existing != packages.end())
                *existing = info;
            else
                packages.push_back(info);
        }

        fclose(file);

        // XESM3 public toggle behavior: 0 disables a mod; 100 enables it.
        // No numeric priority system is exposed; config order is deterministic.
        return true;
    }

    bool SameArchiveIdentity(const ArchiveIdentity& a, const ArchiveIdentity& b)
    {
        if (!a.valid || !b.valid)
            return false;

        if (_stricmp(a.packName.c_str(), b.packName.c_str()) != 0)
            return false;
        if (a.outerHash != b.outerHash)
            return false;

        // The SM3 Toolkit archive folder preserves outer index and type too.
        // When both sides know those values, require an exact match. Legacy
        // .pcapk/.pcpack compatibility may only know the hash.
        if (a.outerIndex != 0 && b.outerIndex != 0 && a.outerIndex != b.outerIndex)
            return false;
        if (a.outerType != 0 && b.outerType != 0 && a.outerType != b.outerType)
            return false;

        return true;
    }

    std::string ArchiveIdentityText(const ArchiveIdentity& identity)
    {
        if (!identity.valid)
            return std::string("<unresolved>");

        char buffer[1024]{};
        sprintf_s(
            buffer,
            "%s/%s [outer=%u hash=%08X type=%02X]",
            identity.packName.empty() ? "<pack?>" : identity.packName.c_str(),
            identity.archiveFolder.empty() ? "<archive?>" : identity.archiveFolder.c_str(),
            identity.outerIndex,
            identity.outerHash,
            identity.outerType);
        return std::string(buffer);
    }

    bool TryParseUnsigned(const std::string& text, int base, uint32_t& value)
    {
        value = 0;
        if (text.empty())
            return false;

        char* end = nullptr;
        const unsigned long parsed = strtoul(text.c_str(), &end, base);
        if (end == text.c_str() || *end != '\0' || parsed > 0xFFFFFFFFul)
            return false;

        value = static_cast<uint32_t>(parsed);
        return true;
    }

    std::string FirstRelativeDirectory(const std::string& root, const std::string& directory)
    {
        if (directory.size() <= root.size() || _strnicmp(directory.c_str(), root.c_str(), root.size()) != 0)
            return std::string();

        size_t start = root.size();
        while (start < directory.size() && (directory[start] == '\\' || directory[start] == '/'))
            ++start;
        if (start >= directory.size())
            return std::string();

        size_t end = directory.find_first_of("\\/", start);
        std::string first = directory.substr(start, end == std::string::npos ? std::string::npos : end - start);

        // Friendly drag/drop compatibility: if someone copies the whole
        // 06_MOD_LOADER_READY directory into a mod instead of copying its
        // contents, treat the next component as the actual source pack.
        if (_stricmp(first.c_str(), "06_MOD_LOADER_READY") == 0 && end != std::string::npos)
        {
            start = end + 1;
            while (start < directory.size() && (directory[start] == '\\' || directory[start] == '/'))
                ++start;
            end = directory.find_first_of("\\/", start);
            first = directory.substr(start, end == std::string::npos ? std::string::npos : end - start);
        }

        return first;
    }

    bool TryGetArchiveScopeFromDirectory(
        const std::string& directory,
        const ModPackageInfo& package,
        ArchiveIdentity& scope)
    {
        scope = ArchiveIdentity{};

        const size_t slash = directory.find_last_of("\\/");
        const std::string leaf = slash == std::string::npos ? directory : directory.substr(slash + 1);
        if (leaf.empty())
            return false;

        // Preferred SM3 Toolkit v5.2.109 format:
        //   _O0384.0xEE185533.T36.apkf
        if (EndsWithInsensitive(leaf, ".apkf") && leaf.size() > 4 &&
            leaf[0] == '_' && (leaf[1] == 'O' || leaf[1] == 'o'))
        {
            const size_t firstDot = leaf.find('.', 2);
            if (firstDot == std::string::npos)
                return false;

            uint32_t outerIndex = 0;
            if (!TryParseUnsigned(leaf.substr(2, firstDot - 2), 10, outerIndex))
                return false;

            uint32_t outerHash = 0;
            if (!TryFindExplicitHashInText(leaf, outerHash, nullptr))
                return false;

            const size_t typeMarker = leaf.find(".T", firstDot);
            const size_t typeMarkerLower = leaf.find(".t", firstDot);
            const size_t marker = typeMarker != std::string::npos ? typeMarker : typeMarkerLower;
            if (marker == std::string::npos)
                return false;

            const size_t typeStart = marker + 2;
            const size_t typeEnd = leaf.find('.', typeStart);
            if (typeEnd == std::string::npos || typeEnd <= typeStart)
                return false;

            uint32_t outerType = 0;
            if (!TryParseUnsigned(leaf.substr(typeStart, typeEnd - typeStart), 16, outerType))
                return false;

            scope.packName = FirstRelativeDirectory(package.root, directory);
            scope.archiveFolder = leaf;
            scope.outerIndex = outerIndex;
            scope.outerHash = outerHash;
            scope.outerType = outerType;
            scope.valid = !scope.packName.empty() && _stricmp(scope.packName.c_str(), leaf.c_str()) != 0 && outerHash != 0;
            return scope.valid;
        }

        // Legacy exWoS-style folder compatibility. We keep this for users who
        // already built Stage 2C v2 test folders, but new SM3 mods should use
        // the _O####.0x########.T##.apkf hierarchy exported by the toolkit.
        if (EndsWithInsensitive(leaf, ".pcapk") || EndsWithInsensitive(leaf, ".pcpack"))
        {
            uint32_t outerHash = 0;
            if (!TryFindExplicitHashInText(leaf, outerHash, nullptr))
                return false;

            scope.packName = FirstRelativeDirectory(package.root, directory);
            scope.archiveFolder = leaf;
            scope.outerHash = outerHash;
            scope.valid = !scope.packName.empty() && _stricmp(scope.packName.c_str(), leaf.c_str()) != 0 && outerHash != 0;
            return scope.valid;
        }

        return false;
    }

    std::vector<std::string> SplitTabFields(const std::string& line)
    {
        std::vector<std::string> fields;
        size_t start = 0;
        while (start <= line.size())
        {
            const size_t tab = line.find('\t', start);
            fields.push_back(line.substr(start, tab == std::string::npos ? std::string::npos : tab - start));
            if (tab == std::string::npos)
                break;
            start = tab + 1;
        }
        return fields;
    }

    bool CatalogVectorContains(const std::vector<ArchiveIdentity>& list, const ArchiveIdentity& value)
    {
        for (const ArchiveIdentity& item : list)
        {
            if (SameArchiveIdentity(item, value))
                return true;
        }
        return false;
    }

    void LoadArchiveCatalogFile(const std::string& path)
    {
        FILE* file = nullptr;
        if (fopen_s(&file, path.c_str(), "r") != 0 || file == nullptr)
            return;

        char buffer[8192]{};
        bool firstLine = true;
        LONG addedRows = 0;
        LONG skippedInvalidOrUnscopedRows = 0;

        while (fgets(buffer, static_cast<int>(sizeof(buffer)), file) != nullptr)
        {
            std::string line = TrimAscii(buffer);
            if (line.empty())
                continue;

            if (firstLine)
            {
                firstLine = false;
                if (StartsWithInsensitive(line, "source_pack\tsource_archive\t"))
                    continue;
            }

            const std::vector<std::string> fields = SplitTabFields(line);
            if (fields.size() < 9)
                continue;

            uint32_t catalogResourceType = 0;
            if (_stricmp(fields[5].c_str(), "TEX") == 0)
                catalogResourceType = ResourceTypeFromExtension(".tex");
            else if (_stricmp(fields[5].c_str(), "MAT") == 0)
                catalogResourceType = ResourceTypeFromExtension(".mat");
            else if (_stricmp(fields[5].c_str(), "SKEL") == 0)
                catalogResourceType = ResourceTypeFromExtension(".skel");
            else
                continue; // Stage 2C v6.7 runtime scoping consumes TEX + MAT + SKEL rows.

            uint32_t outerIndex = 0;
            uint32_t outerHash = 0;
            uint32_t outerType = 0;
            uint32_t resourceHash = 0;
            if (!TryParseUnsigned(fields[2], 10, outerIndex) ||
                !TryParseUnsigned(fields[3], 0, outerHash) ||
                !TryParseUnsigned(fields[4], 0, outerType) ||
                !TryParseUnsigned(fields[6], 0, resourceHash) ||
                resourceHash == 0 || outerHash == 0)
            {
                ++skippedInvalidOrUnscopedRows;
                continue;
            }

            ArchiveIdentity identity{};
            identity.packName = fields[0];
            identity.archiveFolder = fields[1];
            identity.outerIndex = outerIndex;
            identity.outerHash = outerHash;
            identity.outerType = outerType;
            identity.valid = !identity.packName.empty() && !identity.archiveFolder.empty();
            if (!identity.valid)
            {
                ++skippedInvalidOrUnscopedRows;
                continue;
            }

            const uint64_t key = MakeLooseResourceKey(catalogResourceType, resourceHash);
            std::vector<ArchiveIdentity>& candidates = s_ArchiveCatalogByResource[key];
            if (!CatalogVectorContains(candidates, identity))
            {
                candidates.push_back(identity);
                ++addedRows;
                InterlockedIncrement(&s_ArchiveCatalogRowCount);
            }
        }

        fclose(file);

        char line[1400]{};
        sprintf_s(
            line,
            "[ArchiveCatalog] LOAD rowsAdded=%ld skippedInvalidOrUnscoped=%ld totalRows=%ld file=%s",
            addedRows,
            skippedInvalidOrUnscopedRows,
            InterlockedCompareExchange(&s_ArchiveCatalogRowCount, 0, 0),
            path.c_str());
        WriteResourceLogLine(line);
    }

    void LoadMasterCatalogsFromModsRoot(const std::string& modsDirectory)
    {
        std::string masterApkfPath = modsDirectory;
        if (!masterApkfPath.empty() && masterApkfPath.back() != '\\')
            masterApkfPath += "\\";
        masterApkfPath += "filelist.apkf.txt";

        s_MasterArchiveCatalogLoaded = FileExists(masterApkfPath);
        if (s_MasterArchiveCatalogLoaded)
        {
            char masterLine[1400]{};
            sprintf_s(
                masterLine,
                "[ArchiveCatalog] MASTER-APKF path=%s",
                masterApkfPath.c_str());
            WriteResourceLogLine(masterLine);
            LoadArchiveCatalogFile(masterApkfPath);
        }
        else
        {
            char missingLine[1400]{};
            sprintf_s(
                missingLine,
                "[ArchiveCatalog] MASTER-APKF-MISSING path=%s hint=copy filelist.apkf.txt from SM3 Toolkit full-pack scan into Mods",
                masterApkfPath.c_str());
            WriteResourceLogLine(missingLine);
        }

        std::string masterOuterPath = modsDirectory;
        if (!masterOuterPath.empty() && masterOuterPath.back() != '\\')
            masterOuterPath += "\\";
        masterOuterPath += "filelist.txt";
        s_MasterOuterCatalogPresent = FileExists(masterOuterPath);

        char outerLine[1400]{};
        sprintf_s(
            outerLine,
            "[OuterCatalog] MASTER-%s path=%s runtimeUse=REFERENCE-ONLY",
            s_MasterOuterCatalogPresent ? "FOUND" : "MISSING",
            masterOuterPath.c_str());
        WriteResourceLogLine(outerLine);
    }

    void IndexCatalogDirectoryRecursive(const std::string& directory, int depth)
    {
        if (depth > 16 || !DirectoryExists(directory))
            return;

        WIN32_FIND_DATAA findData{};
        const std::string searchPath = directory + "\\*";
        HANDLE findHandle = FindFirstFileA(searchPath.c_str(), &findData);
        if (findHandle == INVALID_HANDLE_VALUE)
            return;

        do
        {
            const char* fileName = findData.cFileName;
            if (strcmp(fileName, ".") == 0 || strcmp(fileName, "..") == 0)
                continue;

            const std::string fullPath = directory + "\\" + fileName;
            if ((findData.dwFileAttributes & FILE_ATTRIBUTE_DIRECTORY) != 0)
            {
                IndexCatalogDirectoryRecursive(fullPath, depth + 1);
                continue;
            }

            if (_stricmp(fileName, "filelist.apkf.txt") == 0)
                LoadArchiveCatalogFile(fullPath);
        }
        while (FindNextFileA(findHandle, &findData));

        FindClose(findHandle);
    }

    bool IntersectArchiveCandidates(
        const std::vector<ArchiveIdentity>& a,
        const std::vector<ArchiveIdentity>& b,
        std::vector<ArchiveIdentity>& output)
    {
        output.clear();
        for (const ArchiveIdentity& left : a)
        {
            if (CatalogVectorContains(b, left) && !CatalogVectorContains(output, left))
                output.push_back(left);
        }
        return !output.empty();
    }

    bool TryResolveRuntimeArchiveLocked(
        void* context,
        uint32_t resourceType,
        uint32_t resourceHash,
        ArchiveIdentity& resolved,
        std::string& reason)
    {
        resolved = ArchiveIdentity{};
        reason.clear();
        if (context == nullptr || resourceHash == 0)
        {
            reason = "invalid-context-or-hash";
            return false;
        }

        const uint64_t key = MakeLooseResourceKey(resourceType, resourceHash);
        const auto catalogIt = s_ArchiveCatalogByResource.find(key);
        if (catalogIt == s_ArchiveCatalogByResource.end() || catalogIt->second.empty())
        {
            reason = "no-filelist.apkf-catalog-row-for-hash";
            return false;
        }

        const std::vector<ArchiveIdentity>& hashCandidates = catalogIt->second;

        const auto resolvedIt = s_RuntimeContextResolved.find(context);
        if (resolvedIt != s_RuntimeContextResolved.end())
        {
            if (CatalogVectorContains(hashCandidates, resolvedIt->second))
            {
                resolved = resolvedIt->second;
                return true;
            }

            // The same heap address can be reused after an APKF unload. If the
            // new hash cannot belong to the old archive, invalidate and relearn.
            s_RuntimeContextResolved.erase(resolvedIt);
            s_RuntimeContextCandidates.erase(context);
        }

        auto candidateIt = s_RuntimeContextCandidates.find(context);
        if (candidateIt == s_RuntimeContextCandidates.end())
        {
            s_RuntimeContextCandidates.emplace(context, hashCandidates);
            candidateIt = s_RuntimeContextCandidates.find(context);
        }
        else
        {
            std::vector<ArchiveIdentity> intersection;
            if (IntersectArchiveCandidates(candidateIt->second, hashCandidates, intersection))
            {
                candidateIt->second.swap(intersection);
            }
            else
            {
                // Most likely a recycled context pointer or catalogs from an
                // unrelated pack. Restart from the current hash candidates.
                candidateIt->second = hashCandidates;
            }
        }

        if (candidateIt->second.size() == 1)
        {
            resolved = candidateIt->second.front();
            s_RuntimeContextResolved[context] = resolved;
            InterlockedIncrement(&s_ResolvedArchiveContextCount);

            char line[1400]{};
            sprintf_s(
                line,
                "[ArchiveScope] RESOLVED context=%p viaHash=%08X archive=%s",
                context,
                resourceHash,
                ArchiveIdentityText(resolved).c_str());
            WriteResourceLogLine(line);
            return true;
        }

        char buffer[256]{};
        sprintf_s(buffer, "catalog-ambiguous-candidates=%u", static_cast<unsigned int>(candidateIt->second.size()));
        reason = buffer;
        return false;
    }

    bool FindScopedNativeTexEntryLocked(
        const ArchiveIdentity& runtimeArchive,
        uint32_t resourceHash,
        NativeTexModEntry& entry)
    {
        for (const NativeTexModEntry& candidate : s_ScopedNativeTexEntries)
        {
            if (candidate.resourceHash == resourceHash && SameArchiveIdentity(candidate.scope, runtimeArchive))
            {
                entry = candidate;
                return true;
            }
        }
        return false;
    }

    bool HasScopedNativeTexForHashLocked(uint32_t resourceHash)
    {
        for (const NativeTexModEntry& candidate : s_ScopedNativeTexEntries)
        {
            if (candidate.resourceHash == resourceHash)
                return true;
        }
        return false;
    }

    bool SelectNativeTexOverrideForRuntime(
        void* context,
        uint32_t resourceHash,
        NativeTexModEntry& entry,
        bool& scoped,
        std::string& reason)
    {
        std::lock_guard<std::mutex> lock(s_ResourceLogMutex);
        entry = NativeTexModEntry{};
        scoped = false;
        reason.clear();

        // v6.5 copies the exWoS ownership rule strictly: a loose resource is
        // identified by PACK + APKF ARCHIVE + TYPE + HASH. A matching hash in
        // another PCPACK is NOT a fallback candidate.
        ArchiveIdentity runtimeArchive{};
        std::string resolveReason;
        const bool archiveResolved = TryResolveRuntimeArchiveLocked(
            context,
            ResourceTypeFromExtension(".tex"),
            resourceHash,
            runtimeArchive,
            resolveReason);

        if (!archiveResolved)
        {
            reason = resolveReason.empty() ? "runtime-pack-archive-unresolved-strict-scope" : resolveReason;
            return false;
        }

        if (FindScopedNativeTexEntryLocked(runtimeArchive, resourceHash, entry))
        {
            scoped = true;
            return true;
        }

        reason = HasScopedNativeTexForHashLocked(resourceHash)
            ? "same-hash-installed-but-different-pack-or-archive"
            : "no-scoped-native-tex-override";
        return false;
    }


    bool FindScopedNativeMatEntryLocked(
        const ArchiveIdentity& runtimeArchive,
        uint32_t resourceHash,
        NativeTexModEntry& entry)
    {
        for (const NativeTexModEntry& candidate : s_ScopedNativeMatEntries)
        {
            if (candidate.resourceHash == resourceHash && SameArchiveIdentity(candidate.scope, runtimeArchive))
            {
                entry = candidate;
                return true;
            }
        }
        return false;
    }

    bool HasScopedNativeMatForHashLocked(uint32_t resourceHash)
    {
        for (const NativeTexModEntry& candidate : s_ScopedNativeMatEntries)
        {
            if (candidate.resourceHash == resourceHash)
                return true;
        }
        return false;
    }

    bool SelectNativeMatOverrideForRuntime(
        void* context,
        uint32_t resourceHash,
        NativeTexModEntry& entry,
        bool& scoped,
        std::string& reason)
    {
        std::lock_guard<std::mutex> lock(s_ResourceLogMutex);
        entry = NativeTexModEntry{};
        scoped = false;
        reason.clear();

        // v6.5 fast path: if the user has not installed any loose MAT with this
        // hash, do not spend time resolving archive ownership and do not emit a
        // SCOPED-NATIVEMAT-WAIT line. This removes the previous startup log spam.
        if (!HasScopedNativeMatForHashLocked(resourceHash))
        {
            reason = "no-native-mat-override";
            return false;
        }

        // STRICT exWoS-style ownership: never let a MAT from H07 satisfy a J05
        // request (or any other cross-PCPACK/cross-APKF hash match).
        ArchiveIdentity runtimeArchive{};
        std::string resolveReason;
        const bool archiveResolved = TryResolveRuntimeArchiveLocked(
            context,
            ResourceTypeFromExtension(".mat"),
            resourceHash,
            runtimeArchive,
            resolveReason);

        if (!archiveResolved)
        {
            reason = resolveReason.empty() ? "runtime-pack-archive-unresolved-strict-scope" : resolveReason;
            return false;
        }

        if (FindScopedNativeMatEntryLocked(runtimeArchive, resourceHash, entry))
        {
            scoped = true;
            return true;
        }

        reason = HasScopedNativeMatForHashLocked(resourceHash)
            ? "same-hash-installed-but-different-pack-or-archive"
            : "no-scoped-native-mat-override";
        return false;
    }


