    bool TryGetStickyNativeMeshOwner(
        void* runtimeMesh,
        void* context,
        uint32_t resourceHash,
        NativeMeshStickyOwner& owner)
    {
        owner = NativeMeshStickyOwner{};
        if (runtimeMesh == nullptr || context == nullptr)
            return false;

        const uintptr_t key = reinterpret_cast<uintptr_t>(runtimeMesh);
        const uintptr_t contextKey = reinterpret_cast<uintptr_t>(context);

        std::lock_guard<std::mutex> lock(s_ResourceLogMutex);
        const auto it = s_NativeMeshStickyOwners.find(key);
        if (it == s_NativeMeshStickyOwners.end())
            return false;

        const NativeMeshStickyOwner& candidate = it->second;
        if (candidate.runtimeMesh != key ||
            candidate.strictContext != contextKey ||
            candidate.hash != resourceHash ||
            candidate.successfulApplyCount == 0 ||
            candidate.entry.path.empty() ||
            !candidate.archive.valid)
        {
            return false;
        }

        owner = candidate;
        return true;
    }

    bool RegisterOrRefreshStickyNativeMeshOwner(
        void* runtimeMesh,
        void* context,
        uint32_t resourceHash,
        const NativeTexModEntry& entry,
        const ArchiveIdentity& archive,
        NativeMeshStickyOwner& owner,
        bool& firstRegistration)
    {
        owner = NativeMeshStickyOwner{};
        firstRegistration = false;

        if (runtimeMesh == nullptr ||
            context == nullptr ||
            entry.path.empty() ||
            !archive.valid)
        {
            return false;
        }

        const uintptr_t key = reinterpret_cast<uintptr_t>(runtimeMesh);
        const uintptr_t contextKey = reinterpret_cast<uintptr_t>(context);

        std::lock_guard<std::mutex> lock(s_ResourceLogMutex);
        auto it = s_NativeMeshStickyOwners.find(key);
        if (it == s_NativeMeshStickyOwners.end())
        {
            NativeMeshStickyOwner fresh{};
            fresh.runtimeMesh = key;
            fresh.strictContext = contextKey;
            fresh.hash = resourceHash;
            fresh.entry = entry;
            fresh.archive = archive;
            fresh.successfulApplyCount = 0;
            s_NativeMeshStickyOwners.emplace(key, fresh);
            owner = fresh;
            firstRegistration = true;
            return true;
        }

        NativeMeshStickyOwner& existing = it->second;
        const bool sameVerifiedOwner =
            existing.hash == resourceHash &&
            existing.strictContext == contextKey &&
            _stricmp(existing.entry.path.c_str(), entry.path.c_str()) == 0 &&
            SameArchiveIdentity(existing.archive, archive);

        if (!sameVerifiedOwner)
        {
            existing.runtimeMesh = key;
            existing.strictContext = contextKey;
            existing.hash = resourceHash;
            existing.entry = entry;
            existing.archive = archive;
            existing.successfulApplyCount = 0;
            firstRegistration = true;
        }
        else
        {
            existing.entry = entry;
            existing.archive = archive;
        }

        owner = existing;
        return true;
    }

    uint32_t MarkStickyNativeMeshApplySuccess(
        void* runtimeMesh,
        void* context,
        uint32_t resourceHash)
    {
        if (runtimeMesh == nullptr || context == nullptr)
            return 0;

        const uintptr_t key = reinterpret_cast<uintptr_t>(runtimeMesh);
        const uintptr_t contextKey = reinterpret_cast<uintptr_t>(context);

        std::lock_guard<std::mutex> lock(s_ResourceLogMutex);
        const auto it = s_NativeMeshStickyOwners.find(key);
        if (it == s_NativeMeshStickyOwners.end())
            return 0;

        NativeMeshStickyOwner& owner = it->second;
        if (owner.hash != resourceHash ||
            owner.strictContext != contextKey)
        {
            return 0;
        }

        ++owner.successfulApplyCount;
        return owner.successfulApplyCount;
    }

    uint32_t MaxMipCountForDimensions(uint32_t width, uint32_t height)
    {
        uint32_t dimension = width > height ? width : height;
        uint32_t count = 0;
        while (dimension != 0)
        {
            ++count;
            dimension >>= 1;
        }
        return count;
    }

    bool CandidateWinsConflict(const NativeTexModEntry& candidate, const NativeTexModEntry& incumbent)
    {
        // All enabled public mods use toggle 100. Resolve duplicate targets
        // deterministically by config order: the earlier enabled entry wins.
        if (candidate.configOrder != incumbent.configOrder)
            return candidate.configOrder < incumbent.configOrder;

        // Multiple matching files inside the same mod use a stable path tie-break.
        return _stricmp(candidate.path.c_str(), incumbent.path.c_str()) < 0;
    }

    const char* ConflictReason(const NativeTexModEntry& winner, const NativeTexModEntry& loser)
    {
        return winner.configOrder != loser.configOrder
            ? "config-order"
            : "same-mod-path-tiebreak";
    }

    bool ReadWholeFile(const std::string& path, std::vector<uint8_t>& bytes, std::string& error)
    {
        bytes.clear();
        FILE* file = nullptr;
        if (fopen_s(&file, path.c_str(), "rb") != 0 || file == nullptr)
        {
            error = "could not open loose resource";
            return false;
        }

        if (fseek(file, 0, SEEK_END) != 0)
        {
            fclose(file);
            error = "could not seek loose resource";
            return false;
        }

        const long length = ftell(file);
        if (length <= 0)
        {
            fclose(file);
            error = "loose resource is empty";
            return false;
        }

        rewind(file);
        bytes.resize(static_cast<size_t>(length));
        const size_t readCount = fread(bytes.data(), 1, bytes.size(), file);
        fclose(file);

        if (readCount != bytes.size())
        {
            bytes.clear();
            error = "could not read complete loose resource";
            return false;
        }

        return true;
    }

    // v7.17.3.2 NativeAPKF dual-dispatch overlay foundation. Full and streamed/range
    // traversals fill this cache only after strict PACK+APKF+TYPE+HASH ownership
    // resolves. Specialized native adapters consume a copy outside the mutex.
    bool TryGetNativeApkfOverlayCandidate(
        void* context,
        uint32_t resourceType,
        uint32_t resourceHash,
        NativeApkfOverlayCandidate& candidate)
    {
        candidate = NativeApkfOverlayCandidate{};
        if (context == nullptr || resourceType == 0 || resourceHash == 0)
            return false;

        NativeApkfOverlayKey key{};
        key.context = reinterpret_cast<uintptr_t>(context);
        key.resourceType = resourceType;
        key.resourceHash = resourceHash;

        std::lock_guard<std::mutex> lock(s_ResourceLogMutex);
        const auto it = s_NativeApkfOverlayCandidates.find(key);
        if (it == s_NativeApkfOverlayCandidates.end())
            return false;

        if (!it->second.archive.valid || it->second.entry.path.empty())
            return false;

        candidate = it->second;
        return true;
    }

    void ClearNativeApkfOverlayCandidatesForContextLocked(void* context)
    {
        if (context == nullptr)
            return;

        const uintptr_t contextKey = reinterpret_cast<uintptr_t>(context);
        for (auto it = s_NativeApkfOverlayCandidates.begin();
             it != s_NativeApkfOverlayCandidates.end();)
        {
            if (it->first.context == contextKey)
                it = s_NativeApkfOverlayCandidates.erase(it);
            else
                ++it;
        }
    }

    bool CacheNativeApkfOverlayCandidateLocked(
        void* context,
        uint32_t resourceType,
        uint32_t resourceHash,
        uint32_t subtype,
        uint32_t groupIndex,
        uint32_t resourceIndex,
        uint32_t dispatchRoute,
        void* component0,
        uintptr_t primaryHandler,
        const NativeTexModEntry& entry,
        const ArchiveIdentity& archive,
        bool& firstLog)
    {
        firstLog = false;
        if (context == nullptr || resourceType == 0 || resourceHash == 0 ||
            entry.path.empty() || !archive.valid)
        {
            return false;
        }

        NativeApkfOverlayKey key{};
        key.context = reinterpret_cast<uintptr_t>(context);
        key.resourceType = resourceType;
        key.resourceHash = resourceHash;

        NativeApkfOverlayCandidate candidate{};
        candidate.entry = entry;
        candidate.archive = archive;
        candidate.subtype = subtype;
        candidate.groupIndex = groupIndex;
        candidate.resourceIndex = resourceIndex;
        candidate.dispatchRoute = dispatchRoute;
        candidate.component0 = reinterpret_cast<uintptr_t>(component0);
        candidate.primaryHandler = primaryHandler;

        const bool inserted =
            s_NativeApkfOverlayCandidates.find(key) == s_NativeApkfOverlayCandidates.end();
        s_NativeApkfOverlayCandidates[key] = candidate;
        firstLog = s_NativeApkfOverlayCandidateLogged.insert(key).second;
        if (inserted)
            InterlockedIncrement(&s_NativeApkfOverlayCandidateCount);
        return true;
    }

    int FindAPKFComponentIndexSafe(void* context, uint32_t componentType)
    {
        __try
        {
            if (context == nullptr)
                return -1;

            uint8_t* const ctx = static_cast<uint8_t*>(context);
            const uint32_t componentCount = *reinterpret_cast<uint32_t*>(ctx + 0x08);
            uint8_t* const componentTable = *reinterpret_cast<uint8_t**>(ctx + 0x0C);

            // The dispatcher builds a 63-entry component pointer array on stack.
            if (componentTable == nullptr || componentCount == 0 || componentCount > 63)
                return -1;

            for (uint32_t i = 0; i < componentCount; ++i)
            {
                if (*reinterpret_cast<uint32_t*>(componentTable + i * 0x18) == componentType)
                    return static_cast<int>(i);
            }
        }
        __except (EXCEPTION_EXECUTE_HANDLER)
        {
            return -1;
        }

        return -1;
    }

    bool TryGetRuntimeTexObjects(
        void* context,
        void** componentPointers,
        uint8_t*& img,
        int& physIndex,
        uint32_t& hash,
        uint32_t& flags,
        char* name,
        size_t nameSize)
    {
        img = nullptr;
        physIndex = -1;
        hash = 0;
        flags = 0;
        if (name != nullptr && nameSize != 0)
            name[0] = '\0';

        const int imgIndex = FindAPKFComponentIndexSafe(context, APKF_COMPONENT_IMG);
        physIndex = FindAPKFComponentIndexSafe(context, APKF_COMPONENT_PHYS);
        if (imgIndex < 0 || physIndex < 0 || componentPointers == nullptr)
            return false;

        __try
        {
            img = static_cast<uint8_t*>(componentPointers[imgIndex]);
            if (img == nullptr || componentPointers[physIndex] == nullptr)
                return false;

            hash = *reinterpret_cast<uint32_t*>(img + 0x0C);
            flags = *reinterpret_cast<uint32_t*>(img + 0x10);

            if (name != nullptr && nameSize != 0)
            {
                const char* runtimeName = *reinterpret_cast<const char**>(img + 0x08);
                if (runtimeName != nullptr)
                    strncpy_s(name, nameSize, runtimeName, _TRUNCATE);
            }

            return true;
        }
        __except (EXCEPTION_EXECUTE_HANDLER)
        {
            img = nullptr;
            physIndex = -1;
            hash = 0;
            flags = 0;
            if (name != nullptr && nameSize != 0)
                name[0] = '\0';
            return false;
        }
    }


