bool IsNativeTexRedirectorInstalled()
{
    return s_NativeTexDetourAttached && !s_NativeTexDetourAttachFailed;
}

bool IsNativeMatRedirectorInstalled()
{
    return s_NativeMatDetourAttached && !s_NativeMatDetourAttachFailed;
}


bool IsNativeMeshRedirectorInstalled()
{
    return s_NativeMeshDetourAttached && !s_NativeMeshDetourAttachFailed;
}

bool IsNativeAnimRedirectorInstalled()
{
    return s_NativeAnimDetourAttached && !s_NativeAnimDetourAttachFailed;
}

bool IsNativeSkelRedirectorInstalled()
{
    return s_NativeSkelDetourAttached && !s_NativeSkelDetourAttachFailed;
}

bool IsResourceRedirectorInstalled()
{
    __try
    {
        const SM3ResourceResolverFn currentResolver =
            *reinterpret_cast<SM3ResourceResolverFn*>(SM3_RESOURCE_RESOLVER_SLOT);
        return currentResolver == &ResourceRedirectHook;
    }
    __except (EXCEPTION_EXECUTE_HANDLER)
    {
        return false;
    }
}

const char* GetResourceStorageMode()
{
    ResolveResourceStorage();
    return s_ResourceStorageFallback ? "LocalAppData" : "Game Folder";
}




